&lt;div class=&quot;presentation navmenudroite&quot;&gt;
&lt;h2 class=&quot;separator&quot;&gt;Les arch&#233;types de druide&lt;a class=&quot;headeranchor&quot; id=&quot;Les_arch&#233;types_de_druide_0&quot; href=&quot;#Les_arch&#233;types_de_druide_0&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;&amp;nbsp;Retour &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Druide.html&quot; title=&quot;Le druide&quot;&gt;classe&lt;/a&gt;.
&lt;ul style=&quot;margin-top:2px&quot;&gt;&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Adepte-Ondin-(Druide).html&quot; title=&quot;Adepte ondin&quot;&gt;Adepte ondin&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Ondin-(Race).html&quot; title=&quot;Les ondins&quot;&gt;Ondin&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Ami-Des-F&#233;es-(Druide).html&quot; title=&quot;Ami des f&#233;es&quot;&gt;Ami des f&#233;es&lt;/a&gt; (&lt;i&gt;UI&lt;/i&gt;)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Arpenteur-De-Monde-(Druide).html&quot; title=&quot;Arpenteur de monde&quot;&gt;Arpenteur de monde&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Aspirant-Naga-(Druide).html&quot; title=&quot;Aspirant naga&quot;&gt;Aspirant naga&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Nagaji-(Race).html&quot; title=&quot;Les nagajis&quot;&gt;nagaji&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chamanes-Animaux-(Druide).html&quot; title=&quot;Chamanes animaux&quot;&gt;Chamanes animaux&lt;/a&gt; (MJRA,AG,AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Changepeau-(Druide).html&quot; title=&quot;Changepeau&quot;&gt;Changepeau&lt;/a&gt; (&lt;i&gt;UI&lt;/i&gt;)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chanteur-Sylvestre-(Druide).html&quot; title=&quot;Chanteur sylvestre&quot;&gt;Chanteur sylvestre&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Elfe.html&quot; title=&quot;Les elfes&quot;&gt;Elfe&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chuchoteur-Sauvage-(Druide).html&quot; title=&quot;Chuchoteur sauvage&quot;&gt;Chuchoteur sauvage&lt;/a&gt; (MCA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Croc-De-La-Nature-(Druide).html&quot; title=&quot;Croc de la nature&quot;&gt;Croc de la nature&lt;/a&gt; (MCA) &lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Druide-Aquatique-(Druide).html&quot; title=&quot;Druide aquatique&quot;&gt;Druide aquatique&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Druide-Arctique-(Druide).html&quot; title=&quot;Druide arctique&quot;&gt;Druide arctique&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Druide-De-La-Jungle-(Druide).html&quot; title=&quot;Druide de la jungle&quot;&gt;Druide de la jungle&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Druide-Des-Cavernes-(Druide).html&quot; title=&quot;Druide des cavernes&quot;&gt;Druide des cavernes&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Druide-Des-D&#233;serts-(Druide).html&quot; title=&quot;Druide des d&#233;serts&quot;&gt;Druide des d&#233;serts&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Druide-Des-Marais-(Druide).html&quot; title=&quot;Druide des marais&quot;&gt;Druide des marais&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Druide-Des-Montagnes-(Druide).html&quot; title=&quot;Druide des montagnes&quot;&gt;Druide des montagnes&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Druide-Des-Ouragans-(Druide).html&quot; title=&quot;Druide des ouragans&quot;&gt;Druide des ouragans&lt;/a&gt; (MMI)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Druide-Des-Plaines-(Druide).html&quot; title=&quot;Druide des plaines&quot;&gt;Druide des plaines&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Druide-Des-Temp&#234;tes-(Druide).html&quot; title=&quot;Druide des temp&#234;tes&quot;&gt;Druide des temp&#234;tes&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Druide-Du-Ciel-(Druide).html&quot; title=&quot;Druide du ciel&quot;&gt;Druide du ciel&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Sylphe-(Race).html&quot; title=&quot;Les sylphes&quot;&gt;Sylphe&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Druide-R&#233;incarn&#233;-(Druide).html&quot; title=&quot;Druide r&#233;incarn&#233;&quot;&gt;Druide r&#233;incarn&#233;&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Druide-Urbain-(Druide).html&quot; title=&quot;Druide urbain&quot;&gt;Druide urbain&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Enfant-De-La-Lune-(Druide).html&quot; title=&quot;Enfant de la lune&quot;&gt;Enfant de la lune&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Enfant-Sauvage-(Druide).html&quot; title=&quot;Enfant sauvage&quot;&gt;Enfant sauvage&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Humain.html&quot; title=&quot;Les humains&quot;&gt;Humain&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Fl&#233;trisseur-(Druide).html&quot; title=&quot;Fl&#233;trisseur&quot;&gt;Fl&#233;trisseur&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Gardien-Antique-(Druide).html&quot; title=&quot;Gardien antique&quot;&gt;Gardien antique&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Homme-Serpent.html&quot; title=&quot;Homme-serpent&quot;&gt;Homme-serpent&lt;/a&gt;) (CM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;M&#233;tamorphe-Sauvage-(Druide).html&quot; title=&quot;M&#233;tamorphe sauvage&quot;&gt;M&#233;tamorphe sauvage&lt;/a&gt; (MCA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Sage-Des-Menhirs-(Druide).html&quot; title=&quot;Sage des menhirs&quot;&gt;Sage des menhirs&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Seigneur-De-La-Meute-(Druide).html&quot; title=&quot;Seigneur de la meute&quot;&gt;Seigneur de la meute&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Surnaturaliste-(Druide).html&quot; title=&quot;Surnaturaliste&quot;&gt;Surnaturaliste&lt;/a&gt; (&lt;i&gt;OO&lt;/i&gt;)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Troll-Furieux-(Druide).html&quot; title=&quot;Troll furieux&quot;&gt;Troll furieux&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Troll.html&quot; title=&quot;Troll&quot;&gt;Troll&lt;/a&gt;) (CM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Urushiol-(Druide).html&quot; title=&quot;Urushiol&quot;&gt;Urushiol&lt;/a&gt; (&lt;i&gt;UI&lt;/i&gt;)&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Manuel des joueurs - R&#232;gles avanc&#233;es (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Advanced Player&#39;s Guide/Manuel des joueurs - R&#232;gles avanc&#233;es&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAPG.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;i&gt;Loin des contr&#233;es verdoyantes de la surface s’&#233;tend un monde d’obscurit&#233;. Cette sombre f&#233;&#233;rie poss&#232;de une beaut&#233; et des merveilles naturelles qui lui sont propres, et rares sont les druides qui cherchent &#224; pr&#233;server ce royaume cach&#233; et &#224; le purifier de toutes les horreurs qui rampent vers la lumi&#232;re.&lt;/i&gt;&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Sens des cavernes (Ext)&lt;a class=&quot;headeranchor&quot; id=&quot;Sens_des_cavernes_Ext_0&quot; href=&quot;#Sens_des_cavernes_Ext_0&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Connaissances.html&quot; title=&quot;Connaissances&quot;&gt;Connaissances&lt;/a&gt; (exploration souterraine) est une &lt;a class=&quot;pagelink&quot; href=&quot;Comp&#233;tences.html&quot; title=&quot;Les comp&#233;tences&quot;&gt;comp&#233;tence&lt;/a&gt; de classe et remplace &lt;a class=&quot;pagelink&quot; href=&quot;Connaissances.html&quot; title=&quot;Connaissances&quot;&gt;Connaissances&lt;/a&gt; (g&#233;ographie). Il re&#231;oit un bonus de +2 sur les &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Jettest.html&quot; title=&quot;test&quot;&gt;tests&lt;/a&gt; impliquant cette &lt;a class=&quot;pagelink&quot; href=&quot;Comp&#233;tences.html&quot; title=&quot;Les comp&#233;tences&quot;&gt;comp&#233;tence&lt;/a&gt; et sur ses &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Jettest.html&quot; title=&quot;test&quot;&gt;tests&lt;/a&gt; de &lt;a class=&quot;pagelink&quot; href=&quot;Survie.html&quot; title=&quot;Survie&quot;&gt;Survie&lt;/a&gt;. Cette capacit&#233; remplace &lt;a class=&quot;pagelink&quot; href=&quot;Druide.html#INSTINCTNATUREL&quot; title=&quot;Le druide&quot;&gt;instinct naturel&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;
&lt;h3 class=&quot;separator&quot;&gt;Pacte avec la nature (Ext)&lt;a class=&quot;headeranchor&quot; id=&quot;Pacte_avec_la_nature_Ext_1&quot; href=&quot;#Pacte_avec_la_nature_Ext_1&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Le personnage a acc&#232;s au &lt;a class=&quot;pagelink&quot; href=&quot;Domaine-De-Lobscurit&#233;.html&quot; title=&quot;Domaine de l&amp;#39;Obscurit&#233;&quot;&gt;domaine de l’Obscurit&#233;&lt;/a&gt;, en plus de ceux normalement permis &#224; sa classe, mais pas aux domaines de l’&lt;a class=&quot;pagelink&quot; href=&quot;Domaine-De-Lair.html&quot; title=&quot;Domaine de l&amp;#39;Air&quot;&gt;Air&lt;/a&gt; et du &lt;a class=&quot;pagelink&quot; href=&quot;Domaine-Du-Climat.html&quot; title=&quot;Domaine du Climat&quot;&gt;Climat&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;
&lt;h3 class=&quot;separator&quot;&gt;Empathie sauvage (Sur)&lt;a class=&quot;headeranchor&quot; id=&quot;Empathie_sauvage_Sur_2&quot; href=&quot;#Empathie_sauvage_Sur_2&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Le personnage peut influencer les &lt;a class=&quot;pagelink&quot; href=&quot;Type-Vase.html&quot; title=&quot;Vase&quot;&gt;vases&lt;/a&gt; &#224; la place des &lt;a class=&quot;pagelink&quot; href=&quot;Type-Cr&#233;ature-Magique.html&quot; title=&quot;Cr&#233;ature magique&quot;&gt;cr&#233;atures magiques&lt;/a&gt;, mais il subira une p&#233;nalit&#233; de -4 sur son &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Jettest.html&quot; title=&quot;test&quot;&gt;jet&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;
&lt;h3 class=&quot;separator&quot;&gt;Ami des souterrains (Ext)&lt;a class=&quot;headeranchor&quot; id=&quot;Ami_des_souterrains_Ext_3&quot; href=&quot;#Ami_des_souterrains_Ext_3&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Niveau.html&quot; title=&quot;niveau&quot;&gt;niveau&lt;/a&gt; 2, un &lt;a class=&quot;pagelink&quot; href=&quot;Druide.html&quot; title=&quot;Le druide&quot;&gt;druide&lt;/a&gt; des cavernes peut se d&#233;placer &#224; sa &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Vitessededeplacement.html&quot; title=&quot;VD&quot;&gt;vitesse&lt;/a&gt; normale et sans p&#233;nalit&#233; dans des zones encombr&#233;es de gravats ou dans des passages &#233;troits. Cette capacit&#233; remplace &lt;a class=&quot;pagelink&quot; href=&quot;Druide.html#DEPLACEMENTFACILITE&quot; title=&quot;Le druide&quot;&gt;d&#233;placement facilit&#233;&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Pied l&#233;ger (Ext)&lt;a class=&quot;headeranchor&quot; id=&quot;Pied_l&#233;ger_Ext_4&quot; href=&quot;#Pied_l&#233;ger_Ext_4&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Niveau.html&quot; title=&quot;niveau&quot;&gt;niveau&lt;/a&gt; 3, il est impossible de d&#233;tecter le personnage par la &lt;a class=&quot;pagelink&quot; href=&quot;Perception-Des-Vibrations-(Capacit&#233;).html&quot; title=&quot;Perception des vibrations&quot;&gt;perception des vibrations&lt;/a&gt;. Cette capacit&#233; remplace &lt;a class=&quot;pagelink&quot; href=&quot;Druide.html#ABSENCEDETRACES&quot; title=&quot;Le druide&quot;&gt;absence de traces&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;
&lt;h3 class=&quot;separator&quot;&gt;R&#233;sistance &#224; la corruption souterraine (Sur)&lt;a class=&quot;headeranchor&quot; id=&quot;R&#233;sistance_&#224;_la_corruption_souterraine_Sur_5&quot; href=&quot;#R&#233;sistance_&#224;_la_corruption_souterraine_Sur_5&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Niveau.html&quot; title=&quot;niveau&quot;&gt;niveau&lt;/a&gt; 4, le &lt;a class=&quot;pagelink&quot; href=&quot;Druide.html&quot; title=&quot;Le druide&quot;&gt;druide&lt;/a&gt; des cavernes re&#231;oit un bonus de +2 sur ses &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;jet de sauvegarde&quot;&gt;jets de sauvegarde&lt;/a&gt; contre les &lt;a class=&quot;pagelink&quot; href=&quot;Capacit&#233;s-Sp&#233;ciales.html#TYPES&quot; title=&quot;Les capacit&#233;s sp&#233;ciales&quot;&gt;capacit&#233;s exceptionnelles&lt;/a&gt; et &lt;a class=&quot;pagelink&quot; href=&quot;Capacit&#233;s-Sp&#233;ciales.html#TYPES&quot; title=&quot;Les capacit&#233;s sp&#233;ciales&quot;&gt;surnaturelles&lt;/a&gt; et sur les &lt;a class=&quot;pagelink&quot; href=&quot;Capacit&#233;s-Sp&#233;ciales.html#TYPES&quot; title=&quot;Les capacit&#233;s sp&#233;ciales&quot;&gt;pouvoirs magiques&lt;/a&gt; des &lt;a class=&quot;pagelink&quot; href=&quot;Type-Vase.html&quot; title=&quot;Vase&quot;&gt;vases&lt;/a&gt; et des &lt;a class=&quot;pagelink&quot; href=&quot;Type-Aberration.html&quot; title=&quot;Aberration&quot;&gt;aberrations&lt;/a&gt;. Cette capacit&#233; remplace &lt;a class=&quot;pagelink&quot; href=&quot;Druide.html#RESISTANCEALAPPELDELANATURE&quot; title=&quot;Le druide&quot;&gt;r&#233;sistance &#224; l&#39;appel de la nature&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;
&lt;h3 class=&quot;separator&quot;&gt;Forme animale (Sur)&lt;a class=&quot;headeranchor&quot; id=&quot;Forme_animale_Sur_6&quot; href=&quot;#Forme_animale_Sur_6&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Un &lt;a class=&quot;pagelink&quot; href=&quot;Druide.html&quot; title=&quot;Le druide&quot;&gt;druide&lt;/a&gt; des cavernes re&#231;oit cette aptitude au niveau 6 et son niveau effectif sera &#233;gal &#224; son niveau de &lt;a class=&quot;pagelink&quot; href=&quot;Druide.html&quot; title=&quot;Le druide&quot;&gt;druide&lt;/a&gt; -2. Il ne peut utiliser ce pouvoir pour adopter une forme v&#233;g&#233;tale. Au niveau 10, il peut se transformer en &lt;a class=&quot;pagelink&quot; href=&quot;Type-Vase.html&quot; title=&quot;Vase&quot;&gt;vase&lt;/a&gt; de &lt;a class=&quot;pagelink&quot; href=&quot;Petites-Et-Grandes-Cr&#233;atures.html&quot; title=&quot;taille&quot;&gt;taille&lt;/a&gt; P ou M comme avec &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Forme-Bestiale-Iii.html&quot; title=&quot;Forme bestiale III&quot;&gt;forme bestiale III&lt;/a&gt;&lt;/i&gt;, et en &lt;a class=&quot;pagelink&quot; href=&quot;Type-Vase.html&quot; title=&quot;Vase&quot;&gt;vase&lt;/a&gt; de &lt;a class=&quot;pagelink&quot; href=&quot;Petites-Et-Grandes-Cr&#233;atures.html&quot; title=&quot;taille&quot;&gt;taille&lt;/a&gt; TP ou G au &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Niveau.html&quot; title=&quot;niveau&quot;&gt;niveau&lt;/a&gt; 12 comme avec &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Forme-Bestiale-Iv.html&quot; title=&quot;Forme bestiale IV&quot;&gt;forme bestiale IV&lt;/a&gt;&lt;/i&gt; (consid&#233;rez les &lt;a class=&quot;pagelink&quot; href=&quot;Type-Vase.html&quot; title=&quot;Vase&quot;&gt;vases&lt;/a&gt; comme des &lt;a class=&quot;pagelink&quot; href=&quot;Type-Cr&#233;ature-Magique.html&quot; title=&quot;Cr&#233;ature magique&quot;&gt;cr&#233;atures magiques&lt;/a&gt; sans bonus d’&lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Ca.html&quot; title=&quot;CA&quot;&gt;armure naturelle&lt;/a&gt;). Lorsqu’il est sous cette forme, il n’a aucune anatomie identifiable et est immunis&#233; aux effets du &lt;a class=&quot;pagelink&quot; href=&quot;Poisons.html&quot; title=&quot;poison&quot;&gt;poison&lt;/a&gt;, de l’&lt;a class=&quot;pagelink&quot; href=&quot;Roublard.html#ATTAQUESOURNOISE&quot; title=&quot;Le roublard&quot;&gt;attaque sournoise&lt;/a&gt; et des &lt;a class=&quot;pagelink&quot; href=&quot;Actions-Simples.html#COUPCRITIQUE&quot; title=&quot;Actions simples&quot;&gt;coups critiques&lt;/a&gt;.
